import {Config, Field, type Infer} from 'alinea'

const TextBlock = Config.type('Text', {
  fields: {text: Field.text('Text', {multiline: true})}
})

const ImageBlock = Config.type('Image', {
  fields: {image: Field.image('Image')}
})

export const blocks = {TextBlock, ImageBlock}

export const Page = Config.document('Page', {
  fields: {blocks: Field.list('Blocks', {schema: blocks})}
})

type Block = Infer<typeof Page>['blocks'][number]

export function Blocks({blocks}: {blocks: Array<Block>}) {
  return blocks.map(block => {
    switch (block._type) {
      case 'TextBlock':
        return <p key={block._id} id={block._anchor}>{block.text}</p>
      case 'ImageBlock':
        return <img key={block._id} src={block.image.src} alt={block.image.alt} />
    }
  })
}
